import type { CharacteristicId, Race, Talent } from "./types";

type Aptitudes = Partial<Record<CharacteristicId, number>>;
type TraitInput = [name: string, properties: string, requirements?: string];

const standardWounds = { strength: 1, endurance: 2, willpower: 1 } satisfies Aptitudes;
const standardScale: [number, number, number] = [15, 20, 25];
const highElfScale: [number, number, number] = [40, 50, 60];
const trait = ([name, properties, requirements = "—"]: TraitInput): Omit<Talent, "id" | "source"> => ({ name, properties, requirements });

function makeRace(input: Omit<Race, "advantages" | "disadvantages" | "traits"> & {
  advantages?: string[];
  disadvantages?: string[];
  traits?: TraitInput[];
}): Race {
  return {
    characteristicScale: standardScale,
    woundFactors: standardWounds,
    advantages: input.advantages ?? [],
    disadvantages: input.disadvantages ?? [],
    ...input,
    traits: (input.traits ?? []).map(trait),
  };
}

